select s.id, s.category_id, s.name, s.price, s.image, s.description, s.status, s.update_time, c.name as categoryName from setmeal s left join category c on s.category_id = c.id

     and s.category_id = #{categoryId} 
     and s.name like concat('%', #{name}, '%') 
     and s.status = #{status} 

order by s.id desc

